# OpenVela 第一个应用实践



本文档将以 `led_rgb` 应用为例，指导开发者如何在 OpenVela 系统（基于 NuttX）中从零开始创建一个新的应用程序。我们将深入解析必要的构建文件（Kconfig, Make\.defs, Makefile）以及源代码实现。



## **1\. 目标**



创建一个名为 `rgb_led` 的命令行应用程序：

- 可以通过命令行参数 `rgb_led <color_value>` 设置 LED 颜色。

- 如果不带参数，则循环显示预定义的颜色序列。

- 支持直接调用 HAL 接口或通过文件系统 `/dev/leds0` 两种方式操作。

## **2\. 目录结构准备**



首先，在 `vendor/allwinnertech/apps/` 目录下创建一个新的文件夹 `led_rgb`。



```Bash
mkdir -p vendor/allwinnertech/apps/led_rgb
```



我们将在该目录下创建以下 4 个核心文件：

1. `Kconfig`: 定义应用的配置选项（菜单项）。

2. `Make.defs`: 告诉构建系统包含此目录。

3. `Makefile`: 定义编译规则、源文件和应用入口信息。

4. `led_demo.c`: 应用程序源代码。

---



## **3\. 实现步骤详解**



### **步骤 1: 配置定义 \(Kconfig\)**



`Kconfig` 文件用于在 `make menuconfig` 界面中生成配置菜单，让我们能够开启或关闭这个应用，并配置其参数。



**文件**: \`vendor/allwinnertech/apps/led\_rgb/Kconfig\`



```Plain Text
# 定义主开关 CONFIG_LED_RGB_TEST
config LED_RGB_TEST
    bool "rgb led test"
    default n
    ---help---
        Enable LED_RGB module.

# 只有打开了主开关，下面的选项才会显示
if LED_RGB_TEST

# 定义是否使用 WS2812 具体实现 (示例依赖)
config LED_RGB_WS2812
    bool "ws2812"
    default n
    depends on WS2812 && DRIVERS_LEDC

# 定义生成的程序名称，默认为 "rgb_led"
config LED_RGB_TEST_PROGNAME
    string "Program name"
    default "rgb_led"
    ---help---
        This is the name of the program that will be used when the NSH ELF
        program is installed.

# 定义任务优先级
config LED_RGB_TEST_PRIORITY
    int "rgb led test task priority"
    default 100

# 定义栈大小
config LED_RGB_TEST_STACKSIZE
    int "rgb led test stack size"
    default DEFAULT_TASK_STACKSIZE

endif
```



\> **注意**: 为了让系统看到这个 Kconfig，你通常还需要确保上级目录（如 \`vendor/allwinnertech/apps/Kconfig\`）中有 \`source "vendor/allwinnertech/apps/led\_rgb/Kconfig"\` 这样的语句。



### **步骤 2: 构建系统挂钩 \(Make\.defs\)**



`Make.defs` 用于告诉顶层构建系统，当配置开启时，将这个目录加入到编译列表中。



**文件**: \`vendor/allwinnertech/apps/led\_rgb/Make\.defs\`



```Makefile
# 如果 CONFIG_LED_RGB_TEST 被选中 (不为空)
ifneq ($(CONFIG_LED_RGB_TEST),)
# 将当前目录加入 CONFIGURED_APPS 列表
CONFIGURED_APPS += $(APPDIR)/vendor/allwinnertech/apps/led_rgb
endif
```



### **3\. 配置编译规则 \(Makefile\)**



`Makefile` 具体指导如何编译这个应用，包括指定源文件、包含路径以及注册为 NSH 内置命令。



**文件**: \`vendor/allwinnertech/apps/led\_rgb/Makefile\`



```Makefile
include $(APPDIR)/Make.defs

# 引入厂商通用的构建规则 (例如 HAL 头文件的路径定义)
include $(APPDIR)/vendor/allwinnertech/Common.mk

# 指定源代码文件
MAINSRC = led_demo.c

# 注册 NSH 内置命令信息
# 这些变量使用了我们在 Kconfig 中定义的值
PROGNAME = $(CONFIG_LED_RGB_TEST_PROGNAME)
PRIORITY = $(CONFIG_LED_RGB_TEST_PRIORITY)
STACKSIZE = $(CONFIG_LED_RGB_TEST_STACKSIZE)
MODULE = $(CONFIG_LED_RGB_TEST)

# 使用 Common.mk 中定义的宏来添加 HAL 相关的头文件路径
# 这是 OpenVela/Allwinner 平台的特定用法，方便引用底层驱动头文件
$(eval $(AW_ADD_HAL_INCLUDES))

# 最后包含标准的 Application.mk 处理实际编译过程
include $(APPDIR)/Application.mk
```



### **4\. 编写应用逻辑 \(led\_demo\.c\)**



最后是实现业务逻辑。我们利用宏 `CONFIG_LED_RGB_WS2812` 来区分是直接调用 HAL 接口还是操作设备文件。



**文件**: \`vendor/allwinnertech/apps/led\_rgb/led\_demo\.c\`



```C
#ifdef __cplusplus
extern "C" {
#endif

#include "sunxi_hal_ledc.h"  // HAL 层接口
#include <debug.h>
#include <fcntl.h>
#include <stdlib.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <unistd.h>

// 颜色定义
#define LED_RED 0xFF0000
#define LED_GREEN 0x00FF00
// ... 其他颜色省略

// 方式一：直接调用 HAL 接口
int hal_test(int count, char **argvs) {
  // 1. 初始化 LED 控制器
  hal_ledc_init();

  if (count < 2) {
    // 循环播放颜色模式
    unsigned int colors[] = {LED_RED, LED_GREEN, LED_BLUE}; 
    // ...
    while (1) {
      for (int i = 0; i < 3; i++) {
        // 设置颜色
        sunxi_set_led_brightness(0, colors[i]);
        sleep(1);
      }
    }
  } else {
    // 命令行参数设置单色模式: rgb_led <color_code>
    int color = atoi(argvs[1]);
    sunxi_set_led_brightness(0, color);
  }

  hal_ledc_deinit();
  return 0;
}

// 方式二：通过文件系统操作 (/dev/leds0)
int file_test(int count, char **argvs) {
  // 1. 打开设备文件
  int fd = open("/dev/leds0", O_RDWR);
  if (fd < 0) {
    _info("open /dev/leds0 failed\n");
    return -1;
  }

  if (count < 2) {
    // 循环播放逻辑...
    int color = LED_RED;
    write(fd, &color, sizeof(int)); // 写入颜色值
    // ...
  } else {
    int color = atoi(argvs[1]);
    write(fd, &color, sizeof(int));
  }

  close(fd);
  return 0;
}

// 主函数入口
int main(int argc, char *argv[]) {
// 根据 Kconfig 配置选择实现方式
#ifdef CONFIG_LED_RGB_WS2812
  return file_test(argc, argv);
#else
  return hal_test(argc, argv);
#endif
}

#ifdef __cplusplus
}
#endif

