+/****************************************************************************
+ * qiban_map_service_main.c
+ *
+ * Board-side map cache service for the "Qiban AI" contest project.
+ ****************************************************************************/
+
+#ifndef _DEFAULT_SOURCE
+#  define _DEFAULT_SOURCE 1
