+#define QIBAN_MAP_DIR              "/data/qiban_map"
+#define QIBAN_MAP_IMAGE_PATH       QIBAN_MAP_DIR "/current.png"
+#define QIBAN_MAP_STATE_PATH       QIBAN_MAP_DIR "/state.json"
