+  printf("Output image: %s\n", QIBAN_MAP_IMAGE_PATH);
+  printf("State file:   %s\n", QIBAN_MAP_STATE_PATH);
+}
+
+int main(int argc, FAR char *argv[])
+{
+  FAR const char *command;
