  qiban_json_write_string(fp, state->source);
  fputs(",\n  \"title\": ", fp);
  qiban_json_write_string(fp, state->title);
  fputs(",\n  \"status\": ", fp);
  qiban_json_write_string(fp, state->status);
  fputs(",\n  \"image_path\": ", fp);
  qiban_json_write_string(fp, state->image_path);
  fprintf(fp, ",\n  \"updated_at\": %ld\n}\n", (long)state->updated_at);

  if (ferror(fp) != 0 || fclose(fp) != 0)
    {
      unlink(QIBAN_MAP_STATE_TEMP_PATH);
      fprintf(stderr, "failed to write %s\n", QIBAN_MAP_STATE_TEMP_PATH);
      return -EIO;
    }

  if (rename(QIBAN_MAP_STATE_TEMP_PATH, QIBAN_MAP_STATE_PATH) != 0)
    {
