    {
      ssize_t offset = 0;

      while (offset < nread)
        {
          ssize_t nwritten = write(dst_fd, buffer + offset, nread - offset);
          if (nwritten < 0)
            {
              close(src_fd);
              close(dst_fd);
              unlink(dst_path);
              return -errno;
            }

          offset += nwritten;
        }
    }

  close(src_fd);
  close(dst_fd);

  if (nread < 0)
    {
      unlink(dst_path);
      return -errno;
    }

  return OK;
}

