+static int qiban_fetch_amap(double longitude, double latitude, int zoom,
+                            FAR const char *title)
+{
+  char url[QIBAN_MAP_AMAP_URL_SIZE];
+  int written;
+  int ret;
+
+  if (zoom < QIBAN_MAP_AMAP_MIN_ZOOM || zoom > QIBAN_MAP_AMAP_MAX_ZOOM)
+    {
+      fprintf(stderr, "zoom out of range: %d\n", zoom);
+      return -ERANGE;
+    }
+
+  written = snprintf(
+    url, sizeof(url),
+    "https://restapi.amap.com/v3/staticmap?"
+    "location=%.6f,%.6f&zoom=%d&size=%s&scale=%d&traffic=1&"
+    "markers=mid,0xFF0000,A:%.6f,%.6f&key=[REDACTED]",
+    longitude, latitude, zoom, QIBAN_MAP_AMAP_SIZE, QIBAN_MAP_AMAP_SCALE,
+    longitude, latitude, QIBAN_MAP_AMAP_KEY);
+  if (written < 0 || written >= (int)sizeof(url))
+    {
+      return -ENAMETOOLONG;
+    }
+
+  ret = qiban_fetch_png(url);
+  if (ret < 0)
+    {
+      qiban_publish_state("wifi:amap",
+                          title != NULL ? title : QIBAN_MAP_AMAP_TITLE,
+                          "amap download failed", false);
+      return ret;
+    }
+
+  return qiban_publish_state("wifi:amap",
+                             title != NULL ? title : QIBAN_MAP_AMAP_TITLE,
+                             "amap map ready", true);
+}
