static void qiban_ui_update_page_indicator(struct qiban_ui_s *ui)
{
  if (ui->active_page == 0)
    {
      lv_obj_add_state(ui->prev_button, LV_STATE_DISABLED);
      lv_obj_remove_state(ui->next_button, LV_STATE_DISABLED);
      lv_label_set_text(ui->page_label, "Dash 1/2");
    }
  else
    {
      lv_obj_remove_state(ui->prev_button, LV_STATE_DISABLED);
      lv_obj_add_state(ui->next_button, LV_STATE_DISABLED);
      lv_label_set_text(ui->page_label, "Map 2/2");
    }
}

static void qiban_ui_set_page(struct qiban_ui_s *ui, int page,
                              lv_anim_enable_t anim_en)
{
  if (ui == NULL || ui->tileview == NULL)
    {
      return;
    }

  if (page < 0)
    {
      page = 0;
    }

  if (page > 1)
    {
      page = 1;
    }

  ui->active_page = page;
  lv_tileview_set_tile_by_index(ui->tileview, (uint32_t)page, 0, anim_en);
  qiban_ui_update_page_indicator(ui);
}

static void qiban_ui_prev_page_event_cb(lv_event_t *event)
{
  (void)event;

  if (g_qiban_ui == NULL)
    {
      return;
    }

  qiban_ui_set_page(g_qiban_ui, g_qiban_ui->active_page - 1, LV_ANIM_ON);
}

static void qiban_ui_next_page_event_cb(lv_event_t *event)
{
  (void)event;

  if (g_qiban_ui == NULL)
    {
      return;
    }

  qiban_ui_set_page(g_qiban_ui, g_qiban_ui->active_page + 1, LV_ANIM_ON);
}

static void qiban_ui_tileview_event_cb(lv_event_t *event)
{
  struct qiban_ui_s *ui;
  lv_obj_t *active_tile;

  if (lv_event_get_code(event) != LV_EVENT_VALUE_CHANGED)
    {
      return;
    }

  ui = g_qiban_ui;
  if (ui == NULL || ui->tileview == NULL)
    {
      return;
    }

  active_tile = lv_tileview_get_tile_active(ui->tileview);
  ui->active_page = active_tile == ui->map_tile ? 1 : 0;
  qiban_ui_update_page_indicator(ui);
}

static void qiban_ui_update_alerts(struct qiban_ui_s *ui)
{
  char alert_text[128];
  lv_color_t color;

  if (ui->state.alert_overspeed)
    {
      snprintf(alert_text, sizeof(alert_text), "Alert: Slow down");
      color = lv_color_hex(0xb91c1c);
    }
  else if (ui->state.alert_low_battery)
    {
      snprintf(alert_text, sizeof(alert_text), "Alert: Charge soon");
      color = lv_color_hex(0xb45309);
    }
  else if (ui->state.alert_fatigue)
    {
      snprintf(alert_text, sizeof(alert_text), "Alert: Take a break");
      color = lv_color_hex(0x1d4ed8);
    }
  else
    {
      snprintf(alert_text, sizeof(alert_text), "Status: Ride stable");
      color = lv_color_hex(0x166534);
    }

  lv_obj_set_style_bg_color(ui->alert_panel, color, 0);
  lv_label_set_text(ui->alert_label, alert_text);
}

static void qiban_ui_refresh_map(struct qiban_ui_s *ui)
{
  lv_label_set_text(ui->map_page_title_label, ui->map_state.title);
  lv_label_set_text(ui->map_page_status_label, ui->map_state.status);
  lv_label_set_text_fmt(ui->map_page_source_label, "SRC  %s",
                        ui->state.source);

  if (ui->map_state.ready)
    {
      if (strcmp(ui->active_map_path, ui->map_state.image_path) != 0 ||
          ui->active_map_updated_at != ui->map_state.updated_at)
        {
          lv_image_set_src(ui->map_page_image, ui->map_state.image_path);
          snprintf(ui->active_map_path, sizeof(ui->active_map_path), "%s",
                   ui->map_state.image_path);
          ui->active_map_updated_at = ui->map_state.updated_at;
        }

      lv_obj_clear_flag(ui->map_page_image, LV_OBJ_FLAG_HIDDEN);
      lv_obj_add_flag(ui->map_page_placeholder, LV_OBJ_FLAG_HIDDEN);
    }
  else
    {
      ui->active_map_path[0] = '\0';
      ui->active_map_updated_at = 0;
      lv_obj_add_flag(ui->map_page_image, LV_OBJ_FLAG_HIDDEN);
      lv_obj_clear_flag(ui->map_page_placeholder, LV_OBJ_FLAG_HIDDEN);
    }
}

static void qiban_ui_refresh_labels(struct qiban_ui_s *ui)
{
  lv_label_set_text_fmt(ui->source_label, "SRC  %s", ui->state.source);
  lv_label_set_text_fmt(ui->speed_label, "%d km/h", ui->state.speed_kmh);
  lv_label_set_text_fmt(ui->battery_label, "Battery  %d%%",
                        ui->state.battery_percent);
  lv_label_set_text_fmt(ui->range_label, "Range    %d km",
                        ui->state.remaining_range_km);
  lv_label_set_text_fmt(ui->ride_label, "Ride     %d min",
                        ui->state.ride_duration_min);
  lv_label_set_text_fmt(ui->distance_label, "Distance %d.%d km",
                        ui->state.total_distance_km_x10 / 10,
                        ui->state.total_distance_km_x10 % 10);
  lv_label_set_text_fmt(ui->nav_label, "Nav      %d m",
                        ui->state.nav_remaining_m);
  qiban_ui_update_alerts(ui);
  qiban_ui_refresh_map(ui);
}

