{
  int ret;

  /* 1. SDIO参数配置 给sdc1接口使用CARD_ALWAYS_PRESENT模式， */
  set_sdio_param(1, 3, NULL);

  /* 2. SDIO设备初始化 */
  g_sdio_dev = sdio_initialize(1);
  ninfo("sdio init\n");

  /* 3. Realtek SDIO初始化 */
  ret = realtek_wl_sdio_init(g_sdio_dev);
  if (ret != 0)
    return ret;

  ninfo("wlan init\n");

  /* 4. Realtek WiFi驱动初始化 */
  ret = realtek_wl_initialize(0);
  if (ret < 0)
