static int qiban_parse_int(FAR const char *text, FAR int *out_value)
{
  FAR char *endptr;
  long value;

  if (text == NULL || *text == '\0')
    {
      return -EINVAL;
    }

  errno = 0;
  value = strtol(text, &endptr, 10);
  if (text == endptr || errno != 0)
    {
      return -EINVAL;
    }

  while (*endptr == ' ' || *endptr == '\t' || *endptr == '\n' ||
         *endptr == '\r')
    {
      endptr++;
    }

  if (*endptr != '\0')
    {
      return -EINVAL;
    }

  if (value < INT_MIN || value > INT_MAX)
    {
      return -ERANGE;
    }

  *out_value = (int)value;
  return OK;
}

static int qiban_parse_coordinate(FAR const char *text, double minimum,
                                  double maximum, FAR double *out_value)
{
  FAR char *endptr;
  double value;

  if (text == NULL || *text == '\0')
    {
      return -EINVAL;
    }

  errno = 0;
  value = strtod(text, &endptr);
  if (text == endptr || errno != 0)
    {
      return -EINVAL;
    }

  while (*endptr == ' ' || *endptr == '\t' || *endptr == '\n' ||
         *endptr == '\r')
    {
      endptr++;
    }

  if (*endptr != '\0')
    {
      return -EINVAL;
    }

  if (value < minimum || value > maximum)
    {
      return -ERANGE;
    }

  *out_value = value;
  return OK;
}

static void qiban_json_write_string(FAR FILE *fp, FAR const char *text)
{
  FAR const unsigned char *cursor;

  fputc('"', fp);
  for (cursor = (FAR const unsigned char *)text;
       cursor != NULL && *cursor != '\0';
       cursor++)
    {
      if (*cursor == '"' || *cursor == '\\')
        {
          fputc('\\', fp);
          fputc(*cursor, fp);
        }
      else if (*cursor == '\n')
        {
          fputs("\\n", fp);
        }
      else if (*cursor == '\r')
        {
          fputs("\\r", fp);
        }
      else if (*cursor == '\t')
        {
          fputs("\\t", fp);
        }
      else
        {
          fputc(*cursor, fp);
        }
    }

  fputc('"', fp);
}

