static size_t qiban_curl_write_cb(FAR void *ptr, size_t size, size_t nmemb,
                                  FAR void *userdata)
{
  struct qiban_curl_sink_s *sink;
  size_t total;

  sink = (struct qiban_curl_sink_s *)userdata;
  total = size * nmemb;

  if (sink == NULL || sink->fp == NULL)
    {
      return 0;
    }

  if (fwrite(ptr, 1, total, sink->fp) != total)
    {
      return 0;
    }

  sink->bytes_written += total;
  return total;
}

static int qiban_fetch_png(FAR const char *url)
{
  struct qiban_curl_sink_s sink;
  CURL *curl;
  CURLcode code;

  sink.fp = fopen(QIBAN_MAP_IMAGE_TEMP_PATH, "wb");
  sink.bytes_written = 0;
  if (sink.fp == NULL)
    {
      fprintf(stderr, "failed to open %s: %d\n",
              QIBAN_MAP_IMAGE_TEMP_PATH, errno);
      return -errno;
    }

  code = curl_global_init(CURL_GLOBAL_DEFAULT);
  if (code != CURLE_OK)
    {
      fclose(sink.fp);
      unlink(QIBAN_MAP_IMAGE_TEMP_PATH);
      fprintf(stderr, "curl_global_init failed: %d\n", code);
      return -EIO;
    }

  curl = curl_easy_init();
  if (curl == NULL)
    {
      curl_global_cleanup();
      fclose(sink.fp);
      unlink(QIBAN_MAP_IMAGE_TEMP_PATH);
      return -ENOMEM;
    }

  curl_easy_setopt(curl, CURLOPT_URL, url);
  curl_easy_setopt(curl, CURLOPT_FOLLOWLOCATION, 1L);
  curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, qiban_curl_write_cb);
  curl_easy_setopt(curl, CURLOPT_WRITEDATA, &sink);
  curl_easy_setopt(curl, CURLOPT_USERAGENT, "qiban_map_service/1.0");
  curl_easy_setopt(curl, CURLOPT_TIMEOUT, 20L);
  curl_easy_setopt(curl, CURLOPT_CONNECTTIMEOUT, 10L);
  curl_easy_setopt(curl, CURLOPT_NOSIGNAL, 1L);

  code = curl_easy_perform(curl);
  curl_easy_cleanup(curl);
  curl_global_cleanup();

  if (fclose(sink.fp) != 0)
    {
      unlink(QIBAN_MAP_IMAGE_TEMP_PATH);
      return -EIO;
    }

  if (code != CURLE_OK || sink.bytes_written == 0)
    {
      unlink(QIBAN_MAP_IMAGE_TEMP_PATH);
      fprintf(stderr, "download failed for %s: %s\n",
              url, curl_easy_strerror(code));
      return -EIO;
    }

  if (rename(QIBAN_MAP_IMAGE_TEMP_PATH, QIBAN_MAP_IMAGE_PATH) != 0)
    {
      unlink(QIBAN_MAP_IMAGE_TEMP_PATH);
      fprintf(stderr, "failed to rename %s to %s: %d\n",
              QIBAN_MAP_IMAGE_TEMP_PATH, QIBAN_MAP_IMAGE_PATH, errno);
      return -errno;
    }

  return OK;
}

static int qiban_fetch_amap(double longitude, double latitude, int zoom,
                            FAR const char *title)
{
  char url[QIBAN_MAP_AMAP_URL_SIZE];
  int written;
  int ret;

  if (zoom < QIBAN_MAP_AMAP_MIN_ZOOM || zoom > QIBAN_MAP_AMAP_MAX_ZOOM)
    {
      fprintf(stderr, "zoom out of range: %d\n", zoom);
      return -ERANGE;
    }

  written = snprintf(
    url, sizeof(url),
    "https://restapi.amap.com/v3/staticmap?"
    "location=%.6f,%.6f&zoom=%d&size=%s&scale=%d&traffic=1&"
    "markers=mid,0xFF0000,A:%.6f,%.6f&key=[REDACTED]",
    longitude, latitude, zoom, QIBAN_MAP_AMAP_SIZE, QIBAN_MAP_AMAP_SCALE,
    longitude, latitude, QIBAN_MAP_AMAP_KEY);
  if (written < 0 || written >= (int)sizeof(url))
    {
      return -ENAMETOOLONG;
    }

  ret = qiban_fetch_png(url);
  if (ret < 0)
    {
      qiban_publish_state("wifi:amap",
                          title != NULL ? title : QIBAN_MAP_AMAP_TITLE,
                          "amap download failed", false);
      return ret;
    }

  return qiban_publish_state("wifi:amap",
                             title != NULL ? title : QIBAN_MAP_AMAP_TITLE,
                             "amap map ready", true);
}

