    {
      return -EINVAL;
    }

  if (value < minimum || value > maximum)
    {
      return -ERANGE;
    }

  *out_value = value;
  return OK;
}

static void qiban_json_write_string(FAR FILE *fp, FAR const char *text)
{
  FAR const unsigned char *cursor;

  fputc('"', fp);
  for (cursor = (FAR const unsigned char *)text;
       cursor != NULL && *cursor != '\0';
       cursor++)
    {
      if (*cursor == '"' || *cursor == '\\')
        {
          fputc('\\', fp);
          fputc(*cursor, fp);
        }
      else if (*cursor == '\n')
        {
          fputs("\\n", fp);
        }
      else if (*cursor == '\r')
        {
          fputs("\\r", fp);
        }
      else if (*cursor == '\t')
        {
          fputs("\\t", fp);
        }
      else
        {
          fputc(*cursor, fp);
        }
    }

  fputc('"', fp);
}

