static void qiban_json_write_string(FAR FILE *fp, FAR const char *text)
{
  FAR const unsigned char *cursor;

  fputc('"', fp);
  for (cursor = (FAR const unsigned char *)text;
       cursor != NULL && *cursor != '\0';
       cursor++)
    {
      if (*cursor == '"' || *cursor == '\\')
        {
          fputc('\\', fp);
          fputc(*cursor, fp);
        }
      else if (*cursor == '\n')
        {
          fputs("\\n", fp);
        }
      else if (*cursor == '\r')
        {
          fputs("\\r", fp);
        }
      else if (*cursor == '\t')
        {
          fputs("\\t", fp);
        }
      else
        {
          fputc(*cursor, fp);
        }
    }

  fputc('"', fp);
}

static int qiban_write_state(FAR const struct qiban_map_state_s *state)
{
  FAR FILE *fp;

  fp = fopen(QIBAN_MAP_STATE_TEMP_PATH, "w");
  if (fp == NULL)
    {
      fprintf(stderr, "failed to open %s: %d\n",
              QIBAN_MAP_STATE_TEMP_PATH, errno);
      return -errno;
    }

  fputs("{\n  \"schema_version\": 1,\n  \"source\": ", fp);
  qiban_json_write_string(fp, state->source);
  fputs(",\n  \"title\": ", fp);
  qiban_json_write_string(fp, state->title);
  fputs(",\n  \"status\": ", fp);
  qiban_json_write_string(fp, state->status);
  fputs(",\n  \"image_path\": ", fp);
  qiban_json_write_string(fp, state->image_path);
  fprintf(fp, ",\n  \"updated_at\": %ld\n}\n", (long)state->updated_at);

  if (ferror(fp) != 0 || fclose(fp) != 0)
    {
      unlink(QIBAN_MAP_STATE_TEMP_PATH);
      fprintf(stderr, "failed to write %s\n", QIBAN_MAP_STATE_TEMP_PATH);
      return -EIO;
