static void qiban_ui_tileview_event_cb(lv_event_t *event)
{
  struct qiban_ui_s *ui;
  lv_obj_t *active_tile;

  if (lv_event_get_code(event) != LV_EVENT_VALUE_CHANGED)
    {
      return;
