static void qiban_ui_request_map_refresh(FAR const char *status_text)
{
  FAR char *argv[] =
  {
    "qiban_map_service",
    "refresh",
    NULL
  };

  if (g_qiban_ui == NULL)
    {
      return;
    }

  if (qiban_ui_spawn_map_service(argv) == OK)
    {
      qiban_ui_set_map_pending(g_qiban_ui,
                               status_text != NULL ? status_text
                                                   : "Refreshing map...");
    }
}

static void qiban_ui_map_pan_event_cb(lv_event_t *event)
{
  FAR const char *direction;
  FAR char *argv[4];

  if (lv_event_get_code(event) != LV_EVENT_CLICKED)
    {
      return;
    }

  direction = (FAR const char *)lv_event_get_user_data(event);
  argv[0] = "qiban_map_service";
  argv[1] = "pan";
  argv[2] = (FAR char *)direction;
  argv[3] = NULL;

  if (qiban_ui_spawn_map_service(argv) == OK)
    {
      qiban_ui_set_map_pending(g_qiban_ui, "Panning map...");
    }
}

static void qiban_ui_map_refresh_event_cb(lv_event_t *event)
{
  if (lv_event_get_code(event) != LV_EVENT_CLICKED)
    {
      return;
    }

  qiban_ui_request_map_refresh("Refreshing map...");
}

static void qiban_ui_update_page_indicator(struct qiban_ui_s *ui)
{
  if (ui->active_page == 0)
    {
      lv_obj_add_state(ui->prev_button, LV_STATE_DISABLED);
      lv_obj_remove_state(ui->next_button, LV_STATE_DISABLED);
      lv_label_set_text(ui->header_label, "Ride Dashboard");
      lv_label_set_text(ui->page_label, "Dashboard 1/2");
      lv_label_set_text(ui->prev_button_label, LV_SYMBOL_LEFT);
      lv_label_set_text(ui->next_button_label, LV_SYMBOL_RIGHT);
      lv_obj_add_flag(ui->map_controls_panel, LV_OBJ_FLAG_HIDDEN);
    }
  else
    {
      lv_obj_remove_state(ui->prev_button, LV_STATE_DISABLED);
      lv_obj_remove_state(ui->next_button, LV_STATE_DISABLED);
      lv_label_set_text(ui->header_label, "Live Map");
      lv_label_set_text(ui->page_label, "Map 2/2");
      lv_label_set_text(ui->prev_button_label, "-");
      lv_label_set_text(ui->next_button_label, "+");
      lv_obj_clear_flag(ui->map_controls_panel, LV_OBJ_FLAG_HIDDEN);
    }
}

static void qiban_ui_set_page(struct qiban_ui_s *ui, int page,
                              lv_anim_enable_t anim_en)
{
  if (ui == NULL || ui->tileview == NULL)
    {
      return;
    }

  if (page < 0)
    {
      page = 0;
    }

  if (page > 1)
    {
      page = 1;
    }

  ui->active_page = page;
  lv_tileview_set_tile_by_index(ui->tileview, (uint32_t)page, 0, anim_en);
  qiban_ui_update_page_indicator(ui);
}

static void qiban_ui_prev_page_event_cb(lv_event_t *event)
{
  FAR char *argv[] =
  {
    "qiban_map_service",
    "zoom",
    "out",
    NULL
  };

  (void)event;

  if (g_qiban_ui == NULL)
    {
      return;
    }

  if (g_qiban_ui->active_page == 0)
    {
      qiban_ui_set_page(g_qiban_ui, g_qiban_ui->active_page - 1, LV_ANIM_ON);
    }
  else if (qiban_ui_spawn_map_service(argv) == OK)
    {
      qiban_ui_set_map_pending(g_qiban_ui, "Zooming out...");
    }
}

